	.C_img			(	w_C_img),
	.B_real			(	w_B_real),
	.B_img			(	w_B_img),
	.D_real			(	w_D_real_tmp),
	.D_img			(	w_D_img_tmp)
 );
/*****************<-------		final output		------->**************/
	assign D_real			= w_D_real_tmp;
	assign D_img				= w_D_img_tmp;
	assign data_out_first	= w_delay_out_first;
	assign data_out_last		= w_delay_out_last;

endmodule

